const impacts=[];function impact(f){if(impacts[f])return impacts[f];let c=document.createElement('canvas');c.width=214;c.height=310;let x=c.getContext('2d');x.drawImage(fx[f],300,0,214,310,0,0,214,310);x.globalCompositeOperation='destination-in';let g=x.createRadialGradient(110,170,40,110,170,125);g.addColorStop(0,'#fff');g.addColorStop(.65,'#fff');g.addColorStop(1,'#fff0');x.fillStyle=g;x.fillRect(0,0,214,310);return impacts[f]=c}

