function mistStamp(kind){if(mistCache[kind])return mistCache[kind];const c=document.createElement('canvas');c.width=c.height=160;const x=c.getContext('2d'),g=x.createRadialGradient(80,80,0,80,80,80);if(kind==='heal'){g.addColorStop(0,'#bdffd48c');g.addColorStop(.3,'#8efbb875');g.addColorStop(.65,'#64e99b38');g.addColorStop(1,'#50d88b00')}else{g.addColorStop(0,'#66339499');g.addColorStop(.35,'#9a57c985');g.addColorStop(.7,'#d29cf13d');g.addColorStop(1,'#c68ff000')}x.fillStyle=g;x.fillRect(0,0,160,160);return mistCache[kind]=c}
function healingGlow(center,age){if(age>=1.1)return;const p=point(center),f=age/1.1,envelope=Math.sin(Math.PI*f),spread=.93+f*.1;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=envelope*.8;ctx.drawImage(mistStamp('heal'),-190*spread,-160*spread,380*spread,320*spread);ctx.globalAlpha=envelope*.22;for(let j=0;j<3;j++){const a=j*2.4+f*.15;ctx.drawImage(mistStamp('heal'),Math.cos(a)*40-105,Math.sin(a)*28-75,210,150)}ctx.globalAlpha=envelope*.65;ctx.fillStyle='#d4ffe0';ctx.shadowColor='#8bf5b4';ctx.shadowBlur=5;for(let j=0;j<12;j++){const a=j*2.399,r=Math.sqrt((j+.5)/12)*130;ctx.beginPath();ctx.arc(Math.cos(a)*r,Math.sin(a)*r*.75-f*24,1.5+(j%3)*.4,0,7);ctx.fill()}ctx.restore()}
