for(const u of battle.units){if(u.cast){if(u.type==='archer'&&u.id<12&&u.variant!=='alchemist'){for(const start of [.6,.8,1]){const age=u.cast.time-start;if(age>=0&&age<.35)rainVolley(point(u.cast.center),age/.35,0)}}if(u.type==='archer'&&u.variant!=='alchemist'&&u.cast.time<.6){const a=visual(u);for(let j=-1;j<=1;j++)arrow(a.x+j*8,a.y-55-u.cast.time*170,-1.2,24,'#ccf4da')}}}
for(const p of battle.projectiles){const a=point(p.origin),b=visual(battle.units[p.to]),f=Math.min(1,p.age/p.duration),x=a.x+(b.x-a.x)*f,y=a.y-45+(b.y-a.y)*f;if(p.kind==='gunhit'){ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(b.y-a.y,b.x-a.x));ctx.scale(2.5,2.5);ctx.shadowColor='#b66aff';ctx.shadowBlur=8;ctx.strokeStyle='#d99bff';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-18,0);ctx.lineTo(4,0);ctx.stroke();ctx.restore()}else if(battle.units[p.from].team===1){ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(b.y-a.y,b.x-a.x));const water=p.kind==='arrow';ctx.shadowColor=water?'#75d9ff':'#719fff';ctx.shadowBlur=10;for(let j=3;j>=0;j--){ctx.globalAlpha=1-j*.22;ctx.fillStyle=water?'#78dcf9':'#779fff';ctx.beginPath();ctx.ellipse(-j*7,Math.sin(p.age*30+j)*2,water?8-j:10-j,water?6-j*.7:7-j,0,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.fillStyle='#e0fcff';ctx.beginPath();ctx.ellipse(1,0,4,3,0,0,7);ctx.fill();ctx.restore()}else if(p.kind==='arrow')arrow(x,y,Math.atan2(b.y-a.y,b.x-a.x),28,'#f1e6b3');else fireball(x,y,11,Math.atan2(b.y-a.y,b.x-a.x))}
for(const e of battle.events){if(battle.units[e.from].hp<=0&&(['ultimate','sword'].includes(e.type)||e.type.startsWith('combo')||e.type.startsWith('flamecombo')))continue;const a=visual(battle.units[e.from]),b=e.center?point(e.center):visual(battle.units[e.to]);if(e.type==='characterFx'){if(e.age<.65){const color={allen:'#ffe399',bruno:'#dcaf60',liv:'#88e6a2',finn:'#ffe98c',luna:'#cdabff',sela:'#96fff0',leon:'#91ceff',sylphie:'#d6a5ff',iris:'#b8faff'}[e.variant]||'#a8edce';ctx.save();ctx.strokeStyle=color;ctx.lineWidth=4;ctx.globalAlpha=1-e.age/.65;ctx.beginPath();ctx.ellipse(b.x,b.y-45,15+e.age*65,10+e.age*45,0,0,7);ctx.stroke();ctx.restore()}}else if(e.type==='heal'){if(e.age<1.1){ctx.save();ctx.globalAlpha=1-e.age/1.1;ctx.fillStyle='#8bff97';ctx.shadowColor='#51db78';ctx.shadowBlur=5;for(let j=0;j<5;j++){const x=b.x+(j-2)*11,y=b.y-25-e.age*60-(j%2)*18;ctx.fillRect(x-2,y-6,4,12);ctx.fillRect(x-6,y-2,12,4)}ctx.restore()}}else if(e.type==='gunfire'){if(e.age<.12){const angle=Math.atan2(b.y-a.y,b.x-a.x);ctx.save();ctx.translate(a.x,a.y-55);ctx.rotate(angle);ctx.translate(42,0);ctx.globalAlpha=1-e.age/.12;ctx.fillStyle='#fff5ba';ctx.shadowColor='#e8ff93';ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(-7,-8);ctx.lineTo(22,0);ctx.lineTo(-7,8);ctx.lineTo(0,0);ctx.fill();ctx.restore()}}else if(e.type==='gunhit'){if(e.age<.45&&!battle.events.some(other=>other!==e&&other.type==='gunhit'&&other.to===e.to&&other.age<e.age)){ctx.save();const f=e.age/.45;ctx.globalAlpha=(1-f)*.7;for(let j=0;j<3;j++){const a=j*2.4,r=24+f*14;ctx.drawImage(mistStamp('poison'),b.x+Math.cos(a)*f*25-r,b.y-40+Math.sin(a)*f*14-r-f*12,r*2,r*2)}ctx.restore()}}else if(e.type==='rain'){if(e.age<.45)rainVolley(b,1,e.age)}else if(e.type==='guard'){ctx.save();ctx.globalAlpha=Math.max(0,1-e.age/1.2);ctx.strokeStyle='#ffe6a1';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(b.x,b.y-43,20+e.age*25,40+e.age*22,0,0,7);ctx.stroke();ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.fillStyle='#ffe8ae';ctx.fillText('+120 護盾',b.x,b.y-106-e.age*15);ctx.restore()}else if(e.type.startsWith('flamecombo')){slash(a,b,+e.type.slice(-1),e.age,false,true)}else if(e.type.startsWith('combo')){slash(a,b,+e.type.slice(-1),e.age)}else if(e.type==='ultimate'){if(e.age<.9){const f=Math.min(11,Math.floor(e.age/.9*12)),dx=b.x-a.x,dy=b.y-a.y;ctx.save();ctx.translate(a.x,a.y-45);ctx.rotate(Math.atan2(dy,dx));ctx.drawImage(fx[f],0,0,365,310,-24,-64,Math.hypot(dx,dy)+48,124);ctx.restore();ctx.save();ctx.translate(b.x,b.y-38);ctx.globalAlpha=Math.max(0,1-e.age);ctx.drawImage(impact(f),-90,-108,180,216);ctx.restore()}}else if(e.type==='sword'){if(battle.units[e.from].team===1){if(e.age<.26){ctx.save();ctx.translate((a.x+b.x)/2,(a.y+b.y)/2-45);ctx.rotate(Math.atan2(b.y-a.y,b.x-a.x));ctx.globalAlpha=1-e.age/.26;ctx.strokeStyle='#ffe1a0';ctx.shadowColor='#f7ab55';ctx.shadowBlur=7;ctx.lineWidth=6*(1-e.age/.3);ctx.beginPath();ctx.moveTo(-10,-30);ctx.quadraticCurveTo(34,-10,14,30);ctx.stroke();ctx.restore()}}else slash(a,b,0,e.age,true)}else if(e.type==='tank'){if(e.age<.25){ctx.save();ctx.translate((a.x+b.x)/2,(a.y+b.y)/2-42);ctx.strokeStyle='#fff2bc';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(0,0,31,21,-.5,-2,1.6);ctx.stroke();ctx.restore()}}if((e.damage>0||e.absorbed>0)&&e.age<.65){if(e.type==='gunhit'&&battle.events.some(other=>other!==e&&other.type==='gunhit'&&other.to===e.to&&other.age<e.age))continue;ctx.save();ctx.globalAlpha=1-e.age/.65;ctx.fillStyle=e.type==='poison'?'#d5a2f4':'#ffe2a0';ctx.font='bold 16px system-ui';ctx.textAlign='center';ctx.fillText(e.damage>0?'-'+(e.type==='gunhit'?battle.events.filter(other=>other.type==='gunhit'&&other.to===e.to&&other.age<.65).reduce((sum,other)=>sum+other.damage,0):e.damage):'吸收 '+e.absorbed,b.x,b.y-90-e.age*24);for(let i=0;i<7;i++){let angle=i*2.4,d=e.age*65;ctx.fillRect(b.x+Math.cos(angle)*d,b.y-45+Math.sin(angle)*d,3,3)}ctx.restore()}}

