let accumulated=0,hudTime=0;function tick(now){const dt=Math.min((now-last)/1000||0,.15);last=now;if(ready&&running&&!battle.result){accumulated+=dt*rate;while(accumulated>=.025&&!battle.result){B.step(battle,.025);accumulated-=.025}hudTime+=dt;if(hudTime>.07){hud();hudTime=0}if(battle.result)finish()}else accumulated=0;draw();requestAnimationFrame(tick)}requestAnimationFrame(tick);
